SELECT p.gender, p.age, s.icu, COUNT(pr.procedure_id) AS num_procedures, date_trunc('day', s.intime) AS admission_day, CASE WHEN date_part('day', s.intime) BETWEEN 1 AND 4 THEN '1-4 days' WHEN date_part('day', s.intime) BETWEEN 5 AND 7 THEN '5-7 days' END AS admission_duration, SUM(CASE WHEN p.gender = 'F' AND p.age BETWEEN 40 AND 50 THEN 1 ELSE 0 END) AS women_40_50_count, SUM(CASE WHEN p.gender = 'F' AND p.age BETWEEN 40 AND 50 THEN CASE WHEN date_part('day', s.intime) BETWEEN 1 AND 4 THEN 1 ELSE 0 END) AS women_40_50_1_4_days_count, SUM(CASE WHEN p.gender = 'F' AND p.age BETWEEN 40 AND 50 THEN CASE WHEN date_part('day', s.intime) BETWEEN 5 AND 7 THEN 1 ELSE 0 END) AS women_40_50_5_7_days_count FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.subject_id = s.subject_id JOIN procedures_icd pr ON a.subject_id = pr.subject_id AND a.hadm_id = pr.hadm_id WHERE p.gender = 'F' AND p.age BETWEEN 45 AND 46 AND p.stroke = 'ischemic' GROUP BY p.gender, p.age, s.icu, admission_day, admission_duration;